	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		LineItem
	 */
		public LineItem createLineItem( CreateLineItemCommand command ) {

		LineItem entity = new LineItem();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setLineItemId( command.getLineItemId() );
            entity.setName( command.getName() );
            entity.setBidAmount( command.getBidAmount() );
            entity.setDailyBudget( command.getDailyBudget() );
            entity.setFrequencyCap( command.getFrequencyCap() );
            entity.setStatus( command.getStatus() );
            entity.setPricingModel( command.getPricingModel() );
            entity.setBidStrategy( command.getBidStrategy() );
            entity.setPacing( command.getPacing() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of LineItem {0} ", entity.toString() );

		return entity;
	}

